// Reports the failed run to Convex so it shows in Admin > Automation errors.
// executionId makes the report idempotent; no payload data (emails etc.) is forwarded, only the error.
const crypto = require('crypto');
const secret = ($env.LENDLOOP_API_SECRET || '').split(',')[0].trim();
if (!secret) throw new Error('LENDLOOP_API_SECRET is not set');
const e = $input.first().json;
const report = {
  workflow: String(e.workflow?.name || 'unknown workflow').slice(0, 120),
  node: e.execution?.lastNodeExecuted ? String(e.execution.lastNodeExecuted).slice(0, 120) : undefined,
  message: String(e.execution?.error?.message || e.trigger?.error?.message || 'Unknown error').slice(0, 1000),
  executionId: e.execution?.id ? String(e.execution.id) : undefined,
};
const body = JSON.stringify(report);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return [{ json: { body, timestamp, signature } }];
